import{_ as i,o as l,c as a,aw as t}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Agile","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/agile/models/agile.md","filePath":"wiki/dev-commit/theory/agile/models/agile.md"}'),r={name:"wiki/dev-commit/theory/agile/models/agile.md"};function o(s,e,n,c,g,d){return l(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="agile" tabindex="-1">Agile <a class="header-anchor" href="#agile" aria-label="Permalink to &quot;Agile&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Определения</p><ul><li><strong>Agile (agile software development)</strong> методология - семейство «гибких» подходов к разработке ПО, основынная на итеративном проходе по scope задач в условиях работы разных специалистов с целью выпуска работоспособного продукта</li><li>Agile предполагает, что при реализации проекта не нужно опираться только на заранее созданные подробные планы. Важно ориентироваться на постоянно меняющиеся условия внешней и внутренней среды и учитывать обратную связь от заказчиков и пользователей. Это поощряет разработчиков и инженеров экспериментировать и искать новые решения, не ограничивая себя жесткими рамками и стандартами</li><li>К отдельным agile-подходам относятся scrum и kanban</li></ul></div><h2 id="роли-в-команде" tabindex="-1">Роли в команде <a class="header-anchor" href="#роли-в-команде" aria-label="Permalink to &quot;Роли в команде&quot;">​</a></h2><ul><li><strong>Product Owner (PO)</strong> - Product Manager в терминологии Scrum</li><li><strong>Product Manager</strong> - отвечает за продукт. Несет ответственность за рождение новых продуктов, их подготовленность к выходу на рынок, ценовые характеристики, его целевую аудиторию и прочие характеристики</li><li><strong>Project Manager (PM)</strong> - отвечает за процесс. Координатор. Отвечает за соблюдение сроков и мониторинг всех зависимостей между командами</li><li><strong>Program Manager</strong></li><li><strong>Product Lead / Product Director / Group Product Manager</strong> - начальник над несколькими PM. Отвечает за несколько продуктов одной ветки и определяет цели на более высоком уровне</li></ul><h2 id="agile-манифест" tabindex="-1">Agile-манифест <a class="header-anchor" href="#agile-манифест" aria-label="Permalink to &quot;Agile-манифест&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="http://agilemanifesto.org/iso/ru/principles.html" target="_blank" rel="noreferrer">http://agilemanifesto.org/iso/ru/principles.html</a></li></ul></div><ol><li>Люди и взаимодействие важнее процессов и инструментов</li><li>Работающий продукт важнее исчерпывающей документации</li><li>Сотрудничество с заказчиком важнее согласования условий контракта. Устные договоренности между сотрудниками, между заказчиком и исполнителем важнее всего, что отражено в планах, договорах и техническом задании</li><li>Готовность к изменениям важнее следования первоначальному плану</li></ol>',7)])])}const h=i(r,[["render",o]]);export{u as __pageData,h as default};
